select d.location, case when d.budget >= 3260000 then 'high' when d.budget >= 1030000 then 'mid' else 'low' end as budget_bucket, sum(e.salary) as total_salary, min(e.salary) as min_salary from employees e left join departments d on e.dept_id = d.id where d.budget >= 1249000 group by d.location, case when d.budget >= 3260000 then 'high' when d.budget >= 1030000 then 'mid' else 'low' end;
